\label{lem:local-projection}
For every \(X\in\mathcal{B}(\mathcal H)\),
\begin{equation}
  \mathsf P_S(X)
  =
  \left[
  \frac{1}{m}\operatorname{Tr}_B X
  -
  \frac{\operatorname{Tr} X}{D}\mathbbm{1}_S
  \right]\otimes\mathbbm{1}_B .
  \label{eq:local-projection-formula}
\end{equation}

\label{def:return-matrix}
The \(q\times q\) local return matrix \(C(t)\) is defined by
\begin{equation}
  C_{ba}(t)
  :=
  \frac1d\operatorname{Tr}\left[
  P_b\Phi_t(P_a)
  \right],
  \qquad
  a,b=1,\ldots,q.
  \label{eq:return-matrix-def}
\end{equation}

\label{lem:traceless-expansion}
For every Hermitian \(X\in\mathcal{B}(\mathcal H_S)\) with \(\operatorname{Tr} X=0\),
\begin{equation}
  X
  =
  \frac1d\sum_{a=1}^q x_aP_a,
  \qquad
  x_a=\operatorname{Tr}(P_aX),
  \label{eq:traceless-expansion}
\end{equation}
and
\begin{equation}
  \sum_{a=1}^q x_a^2
  =
  d\,\operatorname{Tr}(X^2).
  \label{eq:parseval-system}
\end{equation}

\label{lem:trace-HS}
For every operator \(X\) on a \(d\)-dimensional Hilbert space,
\begin{equation}
  \left\lVertX\right\rVert_1
  \le
  \sqrt d\,\left\lVertX\right\rVert_2.
  \label{eq:trace-HS}
\end{equation}

\label{thm:return-controls-thermalisation}
For every Hamiltonian \(H\), every subsystem input state \(\rho_S\), and
every \(t\),
\begin{equation}
  D_{\mathrm{tr}}\left(
  \Phi_t(\rho_S),
  \frac{\mathbbm{1}_S}{d}
  \right)^2
  \le
  \frac{d-1}{4}
  \left\lVertC(t)\right\rVert_{\mathrm{op}}^2
  \le
  \frac{d-1}{4}
  \left\lVertC(t)\right\rVert_{\mathrm F}^2.
  \label{eq:return-controls-thermalisation}
\end{equation}
Here \(\left\lVert\cdot\right\rVert_{\mathrm{op}}\) and
\(\left\lVert\cdot\right\rVert_{\mathrm F}\) are respectively the Euclidean operator and
Frobenius norms of the \(q\times q\) matrix \(C(t)\).

\label{def:manybody-return}
Define
\begin{equation}
  \mathsf K_S(t)
  :=
  \mathsf P_S\mathcal U_t\mathsf P_S
  :
  \mathcal V_S\longrightarrow\mathcal V_S.
  \label{eq:manybody-return}
\end{equation}
Its squared Hilbert--Schmidt norm, which sums the return over all
\(q\) basis directions, is
\begin{equation}
  R_S(t)
  :=
  \left\lVert\mathsf K_S(t)\right\rVert_{\mathrm F}^2.
  \label{eq:return-probability}
\end{equation}

\label{prop:return-equals-C}
For every \(t\),
\begin{equation}
  R_S(t)=\left\lVertC(t)\right\rVert_{\mathrm F}^2.
  \label{eq:return-equals-C}
\end{equation}

\label{lem:Cesaro-orthogonality}
For real numbers \(\omega,\nu\),
\begin{equation}
  \lim_{T\to\infty}
  \frac1T\int_0^T
  e^{it(\omega-\nu)}\,dt
  =
  \begin{cases}
  1,&\omega=\nu,\\
  0,&\omega\ne\nu.
  \end{cases}
  \label{eq:Cesaro-orthogonality}
\end{equation}

\label{thm:exact-return-spectral}
The infinite-time average of the total local return is
\begin{equation}
  \overline{R_S(t)}
  =
  \sum_\omega
  \left\lVert
  \mathsf P_S\mathsf Q_\omega\mathsf P_S
  \right\rVert_{\mathrm F}^2.
  \label{eq:exact-return-spectral}
\end{equation}
Equivalently, in the basis \(\{O_a\}\),
\begin{equation}
  \overline{R_S(t)}
  =
  \sum_{a,b=1}^q
  \sum_\omega
  \left\lvert
  \langle O_b,\mathsf Q_\omega O_a\rangle
  \right\rvert^2.
  \label{eq:exact-return-spectral-components}
\end{equation}

\label{lem:tent-domination}
Fix \(T>0\), \(t_0\in\mathbb R\), and put
\[
  c=t_0+\frac T2,
  \qquad
  w_T(t)
  =
  \left(
  1-\frac{|t-c|}{T}
  \right)_+.
\]
For every nonnegative measurable \(f\),
\begin{equation}
  \frac1T\int_{t_0}^{t_0+T}f(t)\,dt
  \le
  \frac2T\int_{\mathbb R}w_T(t)f(t)\,dt.
  \label{eq:tent-domination}
\end{equation}
Moreover, for every real \(\Delta\),
\begin{equation}
  \frac1T
  \int_{\mathbb R}
  w_T(t)e^{it\Delta}\,dt
  =
  e^{ic\Delta}
  \operatorname{sinc}^2
  \left(
  \frac{T\Delta}{2}
  \right),
  \label{eq:tent-fourier}
\end{equation}
where \(\operatorname{sinc}(0)=1\) and
\(\operatorname{sinc}(x)=\sin x/x\) for \(x\ne0\).

\label{lem:local-spectral-weights-new}
The probability measure \(\mu_S\) is supported in
\([-2\left\lVertH\right\rVert_\infty,2\left\lVertH\right\rVert_\infty]\).  Moreover, for all
Liouvillian frequencies \(\omega,\nu\),
\begin{equation}
  0
  \le
  \operatorname{Tr}_{\mathcal K}(A_\omega A_\nu)
  \le
  q^2\pi_\omega\pi_\nu.
  \label{eq:local-cross-new}
\end{equation}

\label{thm:fejer-local-band}
For every Hamiltonian \(H\), every
\(t_0,T,\varepsilon>0\), and every local input state,
\begin{align}
  \frac1T
  \int_{t_0}^{t_0+T}
  R_S(t)\,dt
  &\le
  4q^2\chi_S(\varepsilon;H)
  \left[
  1+
  \frac{2\pi^2}{3(T\varepsilon)^2}
  \right],
  \label{eq:fejer-local-return}\\
  \frac1T
  \int_{t_0}^{t_0+T}
  D_{\mathrm{tr}}\left(
  \Phi_t(\rho_S),\frac{\mathbbm{1}_S}{d}
  \right)^2dt
  &\le
  (d-1)q^2\chi_S(\varepsilon;H)
  \left[
  1+
  \frac{2\pi^2}{3(T\varepsilon)^2}
  \right].
  \label{eq:fejer-local-trace}
\end{align}
No nondegeneracy assumption on energies or gaps is required.

\label{thm:separated-stationary}
For every local input state,
\begin{equation}
  D_{\mathrm{tr}}\left(
  \overline{\Phi}(\rho_S),\frac{\mathbbm{1}_S}{d}
  \right)^2
  \le
  \frac{d-1}{4}q^2\pi_{0,S}^2.
  \label{eq:separated-stationary}
\end{equation}
Thus exact conserved local memory enters quadratically in the
mean-square trace-distance error.

\label{thm:separated-window}
For every \(t_0,T,\varepsilon>0\) and every local input state,
\begin{align}
  &\frac1T
  \int_{t_0}^{t_0+T}
  D_{\mathrm{tr}}\left(
  \Phi_t(\rho_S),
  \overline{\Phi}(\rho_S)
  \right)^2dt
  \nonumber\\
  &\quad\le
  (d-1)q^2
  m_S
  \widetilde\chi_S(\varepsilon;H)
  \left[
  1+
  \frac{2\pi^2}{3(T\varepsilon)^2}
  \right],
  \label{eq:separated-fluctuation}
\end{align}
and
\begin{align}
  &\frac1T
  \int_{t_0}^{t_0+T}
  D_{\mathrm{tr}}\left(
  \Phi_t(\rho_S),\frac{\mathbbm{1}_S}{d}
  \right)^2dt
  \nonumber\\
  &\quad\le
  \frac{d-1}{2}q^2\pi_{0,S}^2
  +
  2(d-1)q^2
  m_S
  \widetilde\chi_S(\varepsilon;H)
  \left[
  1+
  \frac{2\pi^2}{3(T\varepsilon)^2}
  \right].
  \label{eq:separated-total}
\end{align}

\label{cor:separated-same-scale}
Setting \(\varepsilon=T^{-1}\) gives
\begin{equation}
  \sup_{t_0,\rho_S}
  \frac1T
  \int_{t_0}^{t_0+T}
  D_{\mathrm{tr}}\left(
  \Phi_t(\rho_S),\frac{\mathbbm{1}_S}{d}
  \right)^2dt
  \le
  C_d
  \left[
  \pi_{0,S}^2+
  \widetilde\chi_S(T^{-1};H)
  \right]
  \label{eq:separated-same-scale}
\end{equation}
for a constant \(C_d\) depending only on the subsystem dimension.

\label{thm:linear-dynamical-equivalence}
For the same hypotheses,
\begin{align}
 \frac{\mathcal A_S(T;H)}{4d^2}
 &\le \mathscr E_H(T)
 \le (d-1)q^2\,\mathcal A_S(T;H),\\
 \frac{A_S(T)}{4d^2}
 &\le \mathscr G_H(T)
 \le (d-1)q^2\,A_S(T).
 \label{eq:linear-dynamical-equivalence}
\end{align}
Thus at fixed subsystem dimension the correlation mean square and the
every-window local error are comparable \emph{linearly}.  The nonlinear
conversion in the concentration theorem is not a dynamical necessity.

\label{cor:direct-from-autocorrelation-new}
For every \(T>0\),
\begin{equation}
 \mathscr E_H(T)
 \le \mathfrak c_d\left[\pi_{0,S}^2+2A_S^{\rm F}(T)\right]
 \le \mathfrak c_d\left[\pi_{0,S}^2+4A_S(T)\right].
 \label{eq:direct-from-autocorrelation-new}
\end{equation}
The dependence on the correlation mean square is linear.

\label{lem:pi0-energy-lower}
Let
\[
  \widetilde H
  =
  H-\frac{\operatorname{Tr} H}{D}\mathbbm{1}.
\]
If \(\widetilde H\ne0\), then
\begin{equation}
  \pi_{0,S}
  \ge
  \frac1q
  \frac{
  \left\lVert\mathsf P_S\widetilde H\right\rVert_{2,D}^2
  }{
  \left\lVert\widetilde H\right\rVert_{2,D}^2
  },
  \qquad
  q=d^2-1.
  \label{eq:pi0-energy-lower}
\end{equation}
If \(\widetilde H=0\), the right-hand side is defined as zero and the
inequality remains valid.

\label{thm:Haar-local-pi0-floor}
Fix a subsystem \(S\), independent of \(N\), and suppose it contains one
interaction support \(X_0\in\mathcal E_N\).  Assume
\begin{equation}
  v_{X_0}
  :=
  \frac1{d_{X_0}}
  \operatorname{Tr}_{X_0}(\Lambda_{X_0}^2)
  \ge v_*>0
  \label{eq:vstar-floor}
\end{equation}
uniformly in \(N\).  Then
\begin{equation}
  \mathbb E\,\pi_{0,S}
  \ge
  \frac{v_*}{qC_H}\frac1N.
  \label{eq:Haar-local-pi0-floor}
\end{equation}
Thus, for the unseparated local concentration
\(\chi_S\) defined in Eq.~\eqref{eq:local-chi-new},
\[
  \mathbb E\,\chi_S(\varepsilon;H_N)
  \ge
  \frac{v_*}{qC_H}\frac1N
\]
for every \(\varepsilon>0\).

\label{lem:weak-ETH-zero-new}
Under nondegenerate energies,
\begin{equation}
  \pi_{0,S}
  \le
  \frac{2d}{d^2-1}
  \delta_S(H).
  \label{eq:weak-ETH-zero-new}
\end{equation}

\label{cor:weak-ETH-plus-mixing-new}
Let \(S\) be fixed and suppose the energies are nondegenerate.
If \(\delta_S(H_N)=O(N^{-\gamma})\) and
\(A_S(N^c)=O(N^{-2\kappa})\), then
\begin{equation}
 \mathscr E_{H_N}(N^c)
 =O_S(N^{-2\gamma})+O_S(N^{-2\kappa}).
 \label{eq:weak-ETH-plus-mixing-new}
\end{equation}

\label{prop:clock-spectrum}
For \(m=0,\ldots,n-1\), set
\[
  \theta_{m,\phi}
  =
  \frac{2\pi m}{n}-\frac{\phi}{n}.
\]
Then
\begin{equation}
  \ket{\Psi_{m,\phi}}
  =
  \frac1{\sqrt n}
  \sum_{t=0}^{n-1}
  e^{i\theta_{m,\phi}t}
  \ket{K_{t,\phi}}
  \label{eq:clock-state}
\end{equation}
is an eigenstate of \(H_{\mathrm{FK}}\) with
\begin{equation}
  E_{m,\phi}
  =
  1-\cos\theta_{m,\phi}.
  \label{eq:clock-energy}
\end{equation}

\label{lem:LFSR-cycle-phases}
The classical maximal LFSR fixes the all-zero bit string and forms one
cycle of length \(L\) on the nonzero bit strings.  Consequently its
permutation unitary \(U_F\) has a two-dimensional \(+1\) eigenspace and
the remaining eigenvalues are
\begin{equation}
  e^{i\phi_q}
  =
  e^{-2\pi iq/L},
  \qquad
  q=1,\ldots,L-1.
  \label{eq:LFSR-phases}
\end{equation}

\label{thm:LFSR-external}
For every nonidentity spin Pauli operator \(P\), and every pair of
nontrivial Floquet eigenstates \(\ket{\psi_q},\ket{\psi_{q'}}\),
\begin{equation}
  \left\lvert\bra{\psi_q}P\ket{\psi_{q'}}\right\rvert
  \le
  c_n,
  \qquad
  c_n
  :=
  \frac{2^{1+n/2}}{2^n-1}.
  \label{eq:LFSR-Pauli-input}
\end{equation}

\label{lem:LFSR-static-matrix}
Let \(P\ne\mathbbm{1}\) be a spin Pauli operator, extended trivially to the clock.
For regular static eigenstates,
\begin{equation}
  \left\lvert
  \bra{\Psi_{m,q}}
  P\otimes\mathbbm{1}_{\rm clock}
  \ket{\Psi_{m',q'}}
  \right\rvert
  \le
  c_n.
  \label{eq:LFSR-static-matrix}
\end{equation}

Using Eq.~\eqref{eq:clock-state} and clock orthogonality,
\begin{align}
  &\bra{\Psi_{m,q}}
  P\otimes\mathbbm{1}_{\rm clock}
  \ket{\Psi_{m',q'}}
  \nonumber\\
  &\qquad=
  \frac1n
  \sum_{t=0}^{n-1}
  e^{i(\theta_{m',q'}-\theta_{m,q})t}
  \bra{\psi_q}
  U_{t:0}^\dagger P U_{t:0}
  \ket{\psi_{q'}}.
\end{align}
The LFSR gates are Clifford, so
\(U_{t:0}^\dagger P U_{t:0}\)
is again a nonidentity Pauli operator.  Apply
Eq.~\eqref{eq:LFSR-Pauli-input} term by term and use the triangle
inequality.

\label{lem:arcsine}
The measure \(\nu\) is supported on \([0,2]\) and has density
\begin{equation}
  f_E(u)
  =
  \frac{
  \mathbbm 1_{(0,2)}(u)
  }{
  \pi\sqrt{u(2-u)}
  }.
  \label{eq:energy-density}
\end{equation}

\label{lem:grid-interval}
Let \(\Theta_M=\{2\pi a/M:a=0,\ldots,M-1\}\).
For every interval \(J\subset[0,2\pi)\), with any included or excluded
finite endpoints,
\begin{equation}
 \left|\#(\Theta_M\cap J)-\frac{M|J|}{2\pi}\right|\le1.
 \label{eq:grid-interval}
\end{equation}

\label{lem:kolmogorov}
Let
\[
  F_M(y)=\nu_M((-\infty,y]),
  \qquad
  F(y)=\nu((-\infty,y]).
\]
Then
\begin{equation}
  \sup_{y\in\mathbb R}
  |F_M(y)-F(y)|
  \le
  \frac2M.
  \label{eq:kolmogorov}
\end{equation}

\label{lem:BV}
Let \(\mu_1,\mu_2\) be probability measures with distribution functions
\(G_1,G_2\), and suppose
\(\sup_y|G_1(y)-G_2(y)|\le\eta\).
If \(h\) is absolutely continuous, has compact support, and
\(h'\in L^1(\mathbb R)\), then
\begin{equation}
 \left|\int h\,d\mu_1-\int h\,d\mu_2\right|
 \le\eta\int_{\mathbb R}|h'(y)|dy.
 \label{eq:BV}
\end{equation}

\label{lem:difference-density}
The random variable \(Z\) has an even density \(g\) supported on
\([-2,2]\).  For \(0<z<2\),
\begin{equation}
  g(z)
  =
  \frac1{\pi^2}
  \int_{z-1}^{1}
  \frac{dx}{
  \sqrt{
  (1-x^2)
  (1-(x-z)^2)
  }
  }.
  \label{eq:g-convolution}
\end{equation}
Furthermore,
\begin{equation}
  g(z)
  \le
  \log\left(\frac4{|z|}\right),
  \qquad
  0<|z|<2.
  \label{eq:g-log}
\end{equation}

\label{lem:continuum-concentration}
For every interval \(I\subset\mathbb R\) of length
\(0<\delta\le1\),
\begin{equation}
  \mathbb P(Z\in I)
  \le
  2\delta
  \log\left(\frac{4e}{\delta}\right).
  \label{eq:continuum-concentration}
\end{equation}

\label{lem:cosine-difference-discrepancy}
Let \(U,V\) be independent with law \(\nu_M\), and \(E_1,E_2\)
independent with the continuous law \(\nu\).
For every \(I=[a,b)\), \(a<b\),
\begin{equation}
 \left|\mathbb P(U-V\in I)-\mathbb P(E_1-E_2\in I)\right|
 \le\frac8M.
 \label{eq:two-sided-difference-discrepancy}
\end{equation}

\label{thm:cosine-difference}
For every integer \(M\ge1\) and \(0<\delta\le1\),
\begin{equation}
 N_M(\delta)\le
 2M^2\delta\log(4e/\delta)+8M.
 \label{eq:cosine-difference}
\end{equation}

\label{thm:improved-chi}
Under Theorem~\ref{thm:LFSR-external} and Lemma~\ref{lem:LFSR-static-matrix}, for every \(0<\delta\le1\),
\begin{equation}
  \chi_S(\delta;H_{\rm FK})
  \le
  8n\delta
  \log\left(\frac{4e}{\delta}\right)
  +
  \frac{32}{2^n-1}
  +
  \frac4{2^n}.
  \label{eq:improved-chi}
\end{equation}
In particular,
\begin{equation}
  \chi_S(\delta;H_{\rm FK})
  =
  O\!\left(
  n\delta\log\frac e\delta
  \right)
  +
  O(2^{-n}).
  \label{eq:improved-chi-O}
\end{equation}

Let \(I\) be a frequency interval of width \(\delta\).
The regular energies form a subset of the full \(M\)-point cosine grid.
Therefore the number \(N_{\mathcal R}(I)\) of ordered regular pairs
\((j,k)\) with \(E_j-E_k\in I\) is no larger than the full-grid count of
Theorem~\ref{thm:cosine-difference}:
\begin{equation}
  N_{\mathcal R}(I)
  \le
  2M^2\delta
  \log\left(\frac{4e}{\delta}\right)
  +
  8M.
  \label{eq:NR-improved}
\end{equation}

For regular pairs, Lemma~\ref{lem:LFSR-static-matrix} gives
\[
  |\bra jO_a\ket k|^2\le c_n^2.
\]
Hence their contribution to
Eq.~\eqref{eq:local-weight-matrix} is at most
\[
  \frac{N_{\mathcal R}(I)c_n^2}{D}.
\]

Now consider pairs for which at least one index is exceptional.  Since
\(O_a\) is unitary,
\[
  \sum_k|\bra jO_a\ket k|^2
  =
  \bra jO_a^\dagger O_a\ket j
  =
  1.
\]
There are \(r=2n\) exceptional choices of \(j\), so all pairs with
exceptional first index contribute at most \(r/D\).  The same argument
with the second index contributes at most another \(r/D\).  Counting their
intersection twice only increases the upper bound.  Therefore
\begin{equation}
  \langle O_a,\mathsf Q_IO_a\rangle
  \le
  \frac{N_{\mathcal R}(I)c_n^2}{D}
  +
  \frac{2r}{D}.
  \label{eq:weight-before-algebra}
\end{equation}

We now evaluate the coefficients exactly.  Recall
\[
  M=n(2^n-1),
  \qquad
  D=n2^n,
  \qquad
  c_n^2
  =
  \frac{2^{n+2}}{(2^n-1)^2}.
\]
Then
\begin{align}
  \frac{M^2c_n^2}{D}
  &=
  \frac{
  n^2(2^n-1)^2
  }{
  n2^n
  }
  \frac{
  2^{n+2}
  }{
  (2^n-1)^2
  }
  =
  4n,
  \label{eq:M2-exact}\\
  \frac{8Mc_n^2}{D}
  &=
  8
  \frac{
  n(2^n-1)
  }{
  n2^n
  }
  \frac{
  2^{n+2}
  }{
  (2^n-1)^2
  }
  =
  \frac{32}{2^n-1},
  \label{eq:M-exact}\\
  \frac{2r}{D}
  &=
  \frac{4n}{n2^n}
  =
  \frac4{2^n}.
  \label{eq:r-exact}
\end{align}
Substituting Eq.~\eqref{eq:NR-improved} into
Eq.~\eqref{eq:weight-before-algebra} and then using
Eqs.~\eqref{eq:M2-exact}--\eqref{eq:r-exact} gives
\[
  \langle O_a,\mathsf Q_IO_a\rangle
  \le
  8n\delta
  \log\left(\frac{4e}{\delta}\right)
  +
  \frac{32}{2^n-1}
  +
  \frac4{2^n}.
\]
The right-hand side is independent of \(a\).  Averaging over the
\(q\) local Pauli strings and taking the supremum over \(I\) proves
Eq.~\eqref{eq:improved-chi}.

\label{cor:zero}
Let
\[
  \pi_{0,S}
  =
  \mu_S(\{0\}).
\]
Then
\begin{equation}
  \pi_{0,S}
  \le
  \frac{32}{2^n-1}
  +
  \frac4{2^n}
  =
  O(2^{-n}).
  \label{eq:zero}
\end{equation}

\label{thm:LFSR-infinite-improved}
For every fixed spin-only subsystem \(S\),
\begin{equation}
  \sup_{\rho_S}
  \overline{
  D_{\mathrm{tr}}\left(
  \Phi_t(\rho_S),\frac{\mathbbm{1}_S}{2^s}
  \right)^2
  }
  =
  O_s(2^{-n}).
  \label{eq:LFSR-infinite-improved}
\end{equation}

\label{cor:LFSR-stationary-improved}
For the temporal channel
\(\overline{\Phi}\),
\begin{equation}
  \sup_{\rho_S}
  D_{\mathrm{tr}}\left(
  \overline{\Phi}(\rho_S),\frac{\mathbbm{1}_S}{2^s}
  \right)
  =
  O_s(2^{-n}).
  \label{eq:LFSR-stationary-improved}
\end{equation}

\label{thm:LFSR-direct-T}
For every fixed spin-only subsystem \(S\), there exists
\(C_s>0\) such that for every \(n\) and every \(T\ge1\),
\begin{equation}
  \sup_{t_0\ge0}\sup_{\rho_S}
  \frac1T
  \int_{t_0}^{t_0+T}
  D_{\mathrm{tr}}\left(
  \Phi_t(\rho_S),\frac{\mathbbm{1}_S}{2^s}
  \right)^2dt
  \le
  C_s
  \left[
  \frac{n\log(eT)}{T}
  +
  2^{-n}
  \right].
  \label{eq:LFSR-direct-T}
\end{equation}

\label{cor:LFSR-alpha-improved}
For every fixed \(\alpha>0\),
\begin{equation}
  T_n
  =
  n^{1+\alpha}\log(en)
  \label{eq:LFSR-T-alpha}
\end{equation}
implies
\begin{equation}
  \sup_{t_0,\rho_S}
  \frac1{T_n}
  \int_{t_0}^{t_0+T_n}
  D_{\mathrm{tr}}\left(
  \Phi_t(\rho_S),\frac{\mathbbm{1}_S}{2^s}
  \right)^2dt
  =
  O_{s,\alpha}(n^{-\alpha})
  +
  O_s(2^{-n}).
  \label{eq:LFSR-alpha-improved}
\end{equation}
In particular,
\begin{equation}
  T_n=n^2\log(en)
  \label{eq:LFSR-n2log}
\end{equation}
is sufficient for mean-square error \(O_s(n^{-1})\).

\label{prop:LFSR-small-gap-improved}
The smallest positive energy in the one-clock-particle sector obeys
\begin{equation}
  \Delta_n
  \le
  1-
  \cos\left(
  \frac{2\pi}{n(2^n-1)}
  \right)
  \le
  \frac{2\pi^2}{
  n^2(2^n-1)^2
  }
  =
  O(n^{-2}4^{-n}).
  \label{eq:LFSR-small-gap-improved}
\end{equation}
Consequently
\[
  \Delta_n^{-1}
  =
  \Omega(n^24^n).
\]

\label{lem:difference-lower}
Let \(g\) be the density in
Lemma~\ref{lem:difference-density}.  For every \(0<z\le1/2\),
\begin{equation}
  g(z)
  \ge
  \frac1{2\sqrt2\,\pi^2}
  \log\frac1z.
  \label{eq:g-lower}
\end{equation}

\label{cor:theta-log}
There exist absolute constants \(c,C>0\) such that for every
\(0<\delta\le1/2\),
\begin{equation}
  c\,\delta\log\frac1\delta
  \le
  \mathbb P(0\le Z\le\delta)
  \le
  C\,\delta\log\frac e\delta.
  \label{eq:theta-log}
\end{equation}

\label{ass:general-clock-matrix}
For every normalized traceless local unitary basis element \(O_a\) on the
fixed spin subsystem and every pair \(j,k\) of regular static-clock
eigenstates,
\begin{equation}
  |\bra jO_a\ket k|
  \le c_Q.
  \label{eq:general-clock-cQ}
\end{equation}

\label{thm:general-clock}
Under the distinct-phase grid hypothesis above and
Assumption~\ref{ass:general-clock-matrix}, for every \(0<\delta\le1\),
\begin{equation}
  \chi_S(\delta;H_{\rm clock})
  \le
  \frac{2KL^2c_Q^2}{Q}
  \delta\log\frac{4e}{\delta}
  +
  \frac{8Lc_Q^2}{Q}
  +
  \frac{2r_F}{Q}.
\label{eq:general-clock-chi}
\end{equation}
In particular, if
\[
  c_Q\le\frac{C}{\sqrt Q},
  \qquad
  L\le Q,
  \qquad
  r_F\le r_0
\]
with constants \(C,r_0\) independent of \(Q,K\), then
\begin{equation}
  \chi_S(\delta;H_{\rm clock})
  \le
  2C^2K\delta\log\frac{4e}{\delta}
  +
  \frac{8C^2+2r_0}{Q}.
  \label{eq:general-clock-simple}
\end{equation}

\label{cor:general-clock-window}
Under the simplified hypotheses of
Theorem~\ref{thm:general-clock}, for every fixed subsystem \(S\) there is
a constant \(C_S\) such that, for every \(T\ge1\),
\begin{equation}
  \sup_{t_0,\rho_S}
  \frac1T
  \int_{t_0}^{t_0+T}
  D_{\mathrm{tr}}\left(
  \Phi_t(\rho_S),\frac{\mathbbm{1}_S}{d}
  \right)^2dt
  \le
  C_S
  \left[
  \frac{K\log(eT)}{T}
  +
  \frac1Q
  \right].
  \label{eq:general-clock-window}
\end{equation}
For every fixed \(\alpha>0\), if \(Q\) grows exponentially in \(K\),
target mean-square error \(O(K^{-\alpha})\) is therefore reached on
\[
  T_K=O_\alpha(K^{1+\alpha}\log K).
\]

\label{lem:companion-staircase}
On the computational basis
\(\ket{x_0,\ldots,x_{n-1}}\), define the two-site permutation gates
\begin{equation}
  g_i\ket{a,b}
  =
  \ket{b,a-f_i b},
  \qquad
  1\le i\le n-1,
  \label{eq:gi-prime-power}
\end{equation}
where \(g_i\) acts on sites \(i-1,i\), and define the one-site gate
\begin{equation}
  g_0\ket a
  =
  \ket{-f_0a}
  \label{eq:g0-prime-power}
\end{equation}
on site \(0\).  Then
\begin{equation}
  U_F
  :=
  g_0g_1\cdots g_{n-1},
  \label{eq:UF-staircase}
\end{equation}
with \(g_{n-1}\) applied first, implements the companion map
\begin{align}
  F(x_0,\ldots,x_{n-1})
  &=
  \bigl(
  -f_0x_{n-1},
  x_0-f_1x_{n-1},
  \ldots,
  x_{n-2}-f_{n-1}x_{n-1}
  \bigr).
  \label{eq:companion-map}
\end{align}

\label{lem:prime-power-static-matrix}
Let \(O_a\) be a nonidentity local Weyl basis operator on a fixed set of
data sites, extended trivially to the clock.  For every pair of regular
static-clock eigenstates,
\begin{equation}
  \left\lvert
  \bra{\Psi_{m,q}}
  O_a\otimes\mathbbm{1}_{\rm clock}
  \ket{\Psi_{m',q'}}
  \right\rvert
  \le
  c_Q
  \label{eq:prime-power-static-matrix}
\end{equation}
with \(c_Q\) from
Eq.~\eqref{eq:character-sum-cQ}.

Clock orthogonality gives
\begin{align}
  &\bra{\Psi_{m,q}}
  O_a\otimes\mathbbm{1}_{\rm clock}
  \ket{\Psi_{m',q'}}
  \nonumber\\
  &\qquad=
  \frac1K
  \sum_{t=0}^{K-1}
  e^{i(\theta_{m',q'}-\theta_{m,q})t}
  \bra{\psi_q}
  U_{t:0}^\dagger O_aU_{t:0}
  \ket{\psi_{q'}}.
  \label{eq:prime-power-clock-average}
\end{align}
Every gate \(g_i\) is an invertible linear permutation over
\(\mathbb F_{q_0}\).  Conjugation by such a Clifford permutation maps a
Weyl operator to another Weyl operator, and an invertible conjugation
cannot map a nonidentity operator to the identity.  Thus every
\(U_{t:0}^\dagger O_aU_{t:0}\) is a nonidentity Weyl operator.
Theorem~\ref{thm:character-sum-external} bounds every summand in
Eq.~\eqref{eq:prime-power-clock-average} by \(c_Q\) in modulus.  The
triangle inequality proves the result.

\label{cor:prime-power-improved-full}
For every fixed prime-power local dimension \(q_0\) and every fixed
data subsystem \(S\), the following bounds hold for
\(0<\delta\le1\) and \(T\ge1\), respectively:
\begin{align}
  \chi_S(\delta;H_{\rm FK}^{(q_0)})
  &=
  O_{q_0}\left(
  K\delta\log\frac e\delta
  \right)
  +
  O_{q_0}(q_0^{-n}),
  \label{eq:prime-power-chi-full}\\
  \sup_{t_0,\rho_S}
  \frac1T
  \int_{t_0}^{t_0+T}
  D_{\mathrm{tr}}\left(
  \Phi_t(\rho_S),\frac{\mathbbm{1}_S}{d}
  \right)^2dt
  &=
  O_{S,q_0}\left(
  \frac{K\log(eT)}{T}
  \right)
  +
  O_{S,q_0}(q_0^{-n}).
  \label{eq:prime-power-window-full}
\end{align}
Consequently,
\begin{equation}
  T_K
  =
  O_{\alpha,q_0}
  \left(
  K^{1+\alpha}\log K
  \right)
  \label{eq:prime-power-T-full}
\end{equation}
is sufficient for mean-square error \(O(K^{-\alpha})\).

\label{prop:FK-energy-orthogonal-new}
For any periodic Feynman--Kitaev Hamiltonian of the form
Eq.~\eqref{eq:FK} with at least two clock positions, and every
spin-only subsystem \(S\),
\begin{equation}
  \mathsf P_S
  \left(
  H_{\rm FK}
  -
  \frac{\operatorname{Tr} H_{\rm FK}}{D}\mathbbm{1}
  \right)
  =
  0.
  \label{eq:FK-energy-orthogonal-new}
\end{equation}
Thus the conserved total-energy direction is exactly orthogonal to the
traceless spin-local operator algebra.

\label{prop:clock-factorisation-new}
In the physical second-quantized clock realisation,
\[
  N_c=\sum_t c_t^\dagger c_t
\]
commutes with \(H_{\rm FK}\).  In the invariant sector \(N_c=1\), a
spin-only subsystem factors as
\begin{equation}
  \mathcal H^{(1)}
  =
  \mathcal H_S
  \otimes
  \left(
  \mathcal H_{B_s}
  \otimes
  \mathcal H_{\rm clock}^{(1)}
  \right).
  \label{eq:clock-factorisation-new}
\end{equation}
The bath state used in all preceding theorems is therefore exactly
\begin{equation}
  \tau_B
  =
  \frac{\mathbbm{1}_{B_s}}{\dim\mathcal H_{B_s}}
  \otimes
  \frac{\mathbbm{1}_{\rm clock}^{(1)}}{K},
  \label{eq:clock-bath-new}
\end{equation}
where \(K\) is the clock length.  Every product input
\(\rho_S\otimes\tau_B\) has the same mean energy as the maximally mixed
state in the sector.

\label{lem:bad-time-fraction-new}
Let \(f(t)\ge0\).  If
\[
  \frac1T
  \int_{t_0}^{t_0+T}f(t)^2dt
  \le E_T,
\]
then for every \(\eta>0\),
\begin{equation}
  \frac1T
  \operatorname{meas}
  \left\{
  t\in[t_0,t_0+T]:
  f(t)\ge\eta
  \right\}
  \le
  \frac{E_T}{\eta^2}.
  \label{eq:bad-time-fraction-new}
\end{equation}

\label{cor:quasilinear-fixed-accuracy-new}
For the binary LFSR clock, fix a trace-distance tolerance
\(\eta\in(0,1)\) and a tolerated bad-time fraction
\(\zeta\in(0,1)\).  For all sufficiently large \(n\),
\begin{equation}
  T
  =
  O_S\left(
  \frac{n}{\eta^2\zeta}
  \log\frac{en}{\eta^2\zeta}
  \right)
  \label{eq:quasilinear-window-new}
\end{equation}
is sufficient to guarantee, uniformly in the window starting time and in
the local input,
\begin{equation}
  \frac1T
  \operatorname{meas}
  \left\{
  t\in[t_0,t_0+T]:
  D_{\mathrm{tr}}\left(
  \Phi_t(\rho_S),\frac{\mathbbm{1}_S}{2^s}
  \right)
  \ge\eta
  \right\}
  \le\zeta.
  \label{eq:quasilinear-bad-new}
\end{equation}
For fixed \(\eta,\zeta\), this is \(T=O_S(n\log n)\).

\label{thm:Cui-design-input}


There is a universal constant \(C_0\) such that, for the ensemble
Eq.~\eqref{eq:nearly-local-H} with the reference uniform energy law,
\begin{equation}
 \xi\ge2\log_2(2N/\varepsilon)+C_0
 \quad\Longrightarrow\quad
 \left\|\mathcal M_{\{e^{-i\pi H_N}\}}^{(2)}
       -\mathcal M_{\rm Haar}^{(2)}\right\|_\diamond\le\varepsilon.
 \label{eq:reference-design-condition}
\end{equation}
This is the \(k=2\), exact-Haar-gate specialization of Theorem 3 of
Ref.~\cite{CuiSchusterMaoHuangBrandao2025}.  At time \(\pi\),
independent uniform energies on \([-1,1]\) give independent uniform
phases on the unit circle.  The source's measurable-error conclusion
implies the additive-error conclusion used here.

\label{lem:haar-two-copy-audited}
Let \(F\) swap the two copies of \(\mathbb C^D\), where \(D\ge2\).
For every operator \(X\),
\begin{equation}
 \mathcal M_{\rm Haar}^{(2)}(X)
 =\frac{D\operatorname{Tr} X-\operatorname{Tr}(FX)}{D(D^2-1)}\,\mathbbm{1}
  +\frac{D\operatorname{Tr}(FX)-\operatorname{Tr} X}{D(D^2-1)}\,F.
 \label{eq:haar-two-copy-audited}
\end{equation}

\label{lem:structural-frequencies}
The weights satisfy \(W_\ell\ge0\) and \(\sum_\ell W_\ell=1\), and
\begin{equation}
 \varphi_S(t;J,V)=\sum_{\ell\in\mathcal I}
           W_\ell(V)e^{-it\ell\cdot J}.
 \label{eq:structured-phi}
\end{equation}
If the \(J_{i,u}\) are independent and absolutely continuous, then outside
a probability-zero set, all frequencies with different vectors \(\ell\)
are distinct, and only \(\ell=0\) has frequency zero.  On this event
\begin{align}
 \pi_{0,S}(J,V)&=W_0(V),\\
 \widetilde\varphi_S(t;J,V)
     &=\sum_{\ell\ne0}W_\ell(V)e^{-it\ell\cdot J},\\
 \overline{|\varphi_S|^2}&=\beta(V).
 \label{eq:structural-zero-and-plateau}
\end{align}
No assumption of nondegenerate ordered energy gaps is made.

\label{lem:reference-collision}
For fixed \(V\), let the superscript ``ref'' denote expectation over the
independent uniform energy law.  Then
\begin{align}
 \mathbb E_J^{\rm ref}|\varphi_S(\pi;J,V)|^2&=\beta(V),\\
 \mathbb E_J^{\rm ref}\varphi_S(\pi;J,V)&=W_0(V).
 \label{eq:reference-collision-identities}
\end{align}
Consequently, under Eq.~\eqref{eq:reference-design-condition},
\begin{equation}
 \mathbb E_V\beta(V)\le b_N,\qquad
 \mathbb E_VW_0(V)\le\varepsilon,\qquad
 b_N:=\varepsilon+\frac1{q(D^2-1)}.
 \label{eq:plateau-design-bound}
\end{equation}
These conclusions about \(V\) remain valid when the actual energy
distribution is changed.

\label{thm:scalar-dephasing}
Let all energies be independent, independent of \(V\), and have densities
satisfying Lemma~\ref{lem:bounded-density-fourier} with a common fixed
\(L_0\ge1\).  Put
\[
 r_{L_0}(t)=
 \begin{cases}
 1,&|t|\le L_0,\\
 L_0^2/t^2,&|t|>L_0.
 \end{cases}
\]
For each fixed \(V\),
\begin{align}
 \left|\mathbb E_J|\varphi_S(t)|^2-\beta(V)\right|
 &\le r_{L_0}(t)\,[1-\beta(V)],\\
 \left|\mathbb E_J|\widetilde\varphi_S(t)|^2
          -[\beta(V)-W_0(V)^2]\right|
 &\le r_{L_0}(t).
 \label{eq:scalar-dephasing}
\end{align}
In particular, under the reference-design hypotheses,
\begin{equation}
 \mathbb E|\varphi_S(t)|^2\le b_N+r_{L_0}(t),\qquad
 \mathbb E|\widetilde\varphi_S(t)|^2\le b_N+r_{L_0}(t).
 \label{eq:scalar-dephasing-averaged}
\end{equation}
For the uniform law this gives a remainder \(\min\{1,t^{-2}\}\).

\label{cor:generic-nearly-local-bands}
Fix \(b,c>0\).  Choose the reference error \(\varepsilon=N^{-b}\),
logarithmic patches as in Lemma~\ref{lem:admissible-patches}, and a common
density constant \(L_0\) independent of \(N\).  At \(T_N=N^c\),
\begin{equation}
 \mathbb E A_S(T_N)
     =O_{b,L_0}\!\left(N^{-\min\{b,c\}}\right),\qquad
 \mathbb E\mathscr E_H(T_N)
     =O_{s,b,L_0}\!\left(N^{-\min\{b,c\}}\right).
 \label{eq:structured-polynomial-rates}
\end{equation}
For every \(0<a<\min\{b,c\}\),
\begin{equation}
 \mathbb P[\mathscr E_H(N^c)>N^{-a}]
 \le \mathfrak c_d
       \left(N^{a-b}+\frac{N^a}{q(2^{2N}-1)}
                   +4L_0N^{a-c}\right).
 \label{eq:structured-high-probability}
\end{equation}
For example, \(b=c=2\) gives expected every-window mean-square error
\(O_s(N^{-2})\), and error at most \(N^{-1}\) with failure probability
\(O_s(N^{-1})\), on windows \(N^2\).

\label{prop:structured-short-time-lower}
In the structured ensemble, fix \(s\ge1\) qubits, put \(d=2^s\) and
\(a_d=1-1/d\).  Every realization satisfies, for \(T\ge1\),
\begin{equation}
 \mathscr E_H(T)\ge\frac{a_d^3}{40s\,T}.
 \label{eq:structured-short-time-lower}
\end{equation}
Consequently, for \(\varepsilon=N^{-b}\) and \(1\le T\le N^b\),
\(\mathbb E\mathscr E_H(T)=\Theta_{s,b,L_0}(T^{-1})\) for all
sufficiently large admissible \(N\).
This lower bound records the unavoidable initial transient in a
criterion that includes the window starting at zero; it is not a
pointwise long-time lower bound.

\label{cor:all-longer-windows}
For a fixed Hamiltonian, if \(\mathscr E_H(T)\le u\), then for every
\(L\ge T\), every \(t_0\ge0\), and every trace-distance tolerance
\(\eta>0\),
\begin{equation}
 \frac1L\operatorname{meas}\left\{t\in[t_0,t_0+L]:
       \sup_{\rho_S}D_{\mathrm{tr}}(\Phi_t(\rho_S),\mathbbm{1}_S/d)\ge\eta\right\}
 \le\frac{2u}{\eta^2}.
 \label{eq:common-good-times}
\end{equation}
For \(L=T\) the factor two may be omitted.

\label{thm:positive-kernel-stability}
Let \(G,H\) be arbitrary finite Hamiltonians on the same Hilbert space
and suppose \(\|H-G\|_\infty\le\delta\).  For every \(T>0\),
\begin{equation}
 \mathscr E_H(T)
 \le\mathfrak c_d\left[
       2\mathcal F_S(T;G)+\frac43\delta^2T^2\right].
 \label{eq:positive-kernel-stability}
\end{equation}
In particular, if \(G\) is drawn from the structured ensemble and
\(H=G+W_N\), with \(W_N\) an arbitrary measurable perturbation,
possibly dependent on \(G\), and
\(\|W_N\|_\infty\le\delta_N\) for every realization, then
\begin{equation}
 \mathbb E\mathscr E_H(T)
 \le\mathfrak c_d\left[
       2b_N+\frac{8L_0}{T}+\frac43\delta_N^2T^2\right].
 \label{eq:structured-stability}
\end{equation}
The perturbation need not preserve the commuting terms or their
conserved projectors.
